                .timeout(15 * 1000)
                .execute();
            body[0] = res.body();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }

    });

    runner.start();
    Thread.sleep(1000 * 3);
    runner.interrupt();
    assertTrue(runner.isInterrupted());
}

