@Test
public void totalTimeout_1_oe() throws IOException {
    int timeout = 3 * 1000;
    long start = System.currentTimeMillis();
    boolean threw = false;
    try {
        Jsoup.connect(SlowRider.Url).timeout(timeout).get();
    } catch (SocketTimeoutException e) {
        long end = System.currentTimeMillis();
        long took = end - start;
        assertTrue(took > timeout, ("Time taken was " + took));
}
}

@Test
public void totalTimeout_2_oe() throws IOException {
    int timeout = 3 * 1000;
    long start = System.currentTimeMillis();
    boolean threw = false;
    try {
        Jsoup.connect(SlowRider.Url).timeout(timeout).get();
    } catch (SocketTimeoutException e) {
        long end = System.currentTimeMillis();
        long took = end - start;
        assertTrue(took < timeout * 1.8, ("Time taken was " + took));
}
}

